declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}$_SERVER['REQUEST_METHOD']='CLI';require_once __DIR__.'/../config/db.php';$c=db();$failed=false;$checks=['reopening reasons'=>"SELECT COUNT(*) n FROM erp_period_reopenings WHERE CHAR_LENGTH(reason)<20",'prior filed archive preservation'=>"SELECT COUNT(*) n FROM erp_period_reopenings WHERE previous_status='FILED' AND prior_filing_archive_id IS NULL",'archive sequence uniqueness'=>"SELECT COUNT(*) n FROM(SELECT user_id,declaration_type,source_entity_id,filing_sequence FROM erp_filing_archives GROUP BY user_id,declaration_type,source_entity_id,filing_sequence HAVING COUNT(*)>1)x"];
foreach($checks as $label=>$sql){$n=(int)$c->query($sql)->fetch_assoc()['n'];if($n){$failed=true;fwrite(STDERR,"FAIL $label: $n mismatch(es)\n");}else echo "PASS $label reconciles\n";}exit($failed?1:0);
